pub fn field(self: *const Table, name: []const u8) Field {
        _ = &self;
            _ = @setEvalBranchQuota(20000);
            for (self.fields) |f| {
                if (std.mem.eql(u8, (if (@typeInfo(@TypeOf(f)) == .@"enum" or @typeInfo(@TypeOf(f)) == .@"union") @tagName(f) else f.name), name)) {
                    return f;
                }
            }
            _ = @compileError(std.fmt.comptimePrint("Field '{s}' not found in Table", .{ name }));
    }

pub fn resolve(self: *const Table) Table {
            if (((self.stages != .auto) and (self.packing != .auto))) {
                return self.*;
            }
            const can_be_packed = (switch (self.packing) {
.auto, .@"packed" => blk: {
            for (self.fields) |f| {
                if ((!f.canBePacked())) {
                    break :blk false;
                }
            }
            break :blk true;
},
.unpacked => false,
});
            const DataUnpacked = types.Data(Table{ .packing = .unpacked, .fields = self.fields });
            const DataPacked = (if (can_be_packed) types.Data(Table{ .packing = .@"packed", .fields = self.fields }) else DataUnpacked);
            const unpacked_size = @sizeOf(DataUnpacked);
            const packed_size = @sizeOf(DataPacked);
            const min_size = @min(unpacked_size, packed_size);
            const stages: TableStages = (switch (self.stages) {
.auto => blk: {
            if ((min_size <= two_stage_size_threshold)) {
                break :blk .two;
            } else {
                break :blk .three;
            }
},
.two => .two,
.three => .three,
});
            const packing: TablePacking = (switch (self.packing) {
.auto => blk: {
            if ((!can_be_packed)) {
                break :blk .unpacked;
            }
            if (((unpacked_size == min_size) or (unpacked_size <= two_stage_size_threshold))) {
                break :blk .unpacked;
            }
            if ((stages == .two)) {
                if ((packed_size <= two_stage_size_threshold)) {
                    break :blk .@"packed";
                } else {
                    if (((3 * packed_size) <= (2 * unpacked_size))) {
                        break :blk .@"packed";
                    } else {
                        break :blk .unpacked;
                    }
                }
            } else {
                if ((packed_size <= (unpacked_size / 2))) {
                    break :blk .@"packed";
                } else {
                    break :blk .unpacked;
                }
            }
},
.@"packed" => .@"packed",
.unpacked => .unpacked,
});
            return Table{ .stages = stages, .packing = packing, .name = self.name, .extensions = self.extensions, .fields = self.fields };
    }
    pub const Stages = TableStages;
    pub const Packing = TablePacking;
};

pub const Extension = struct {
    inputs: []const [:0]const u8,
    fields: []const Field,
    compute: *const fn (std.mem.Allocator, u21, anytype, anytype, anytype) std.mem.Allocator.Error!void,

pub fn hasField(self: *const Extension, name: []const u8) bool {
        _ = &self;
            inline for (self.fields) |f| {
                if (std.mem.eql(u8, (if (@typeInfo(@TypeOf(f)) == .@"enum" or @typeInfo(@TypeOf(f)) == .@"union") @tagName(f) else f.name), name)) {
                    return true;
                }
            }
            return false;
    }

pub fn field(self: *const Extension, name: []const u8) Field {
        _ = &self;
            for (self.fields) |f| {
                if (std.mem.eql(u8, (if (@typeInfo(@TypeOf(f)) == .@"enum" or @typeInfo(@TypeOf(f)) == .@"union") @tagName(f) else f.name), name)) {
                    return f;
                }
            }
            _ = @compileError(std.fmt.comptimePrint("Field '{s}' not found in Extension", .{ name }));
    }
};

const Str = []const u8;
const CpSlice = []const u21;
const SccSlice = []const types.SpecialCasingCondition;
const OptU4 = ?u4;
const OptU21 = ?u21;
const TypeU8 = u8;
const TypeU21 = u21;
const TypeBool = bool;

pub fn isPackable(comptime T: type) bool {
        switch (@typeInfo(T)) {
.int => |int| {
return (int.bits <= @bitSizeOf(isize));
},
.@"enum" => |e| {
return (@typeInfo(e.tag_type).int.bits <= @bitSizeOf(isize));
},
.bool => {
return true;
},
else => {
return false;
},
}
}

pub fn FieldArray(comptime n: usize) type {
        return [n]Field;
}

pub fn _resolveFields(comptime config_x: type, comptime field_names: []const []const u8, comptime extension_names: []const []const u8) FieldArray(field_names.len) {
        _ = @setEvalBranchQuota(100000);
        var result: FieldArray(field_names.len) = undefined;
        _ = &result;
        for (field_names, 0..) |field_name, i| {
            var found = false;
            _ = &found;
            inline for (@typeInfo(config_x).@"struct".decls) |decl| {
                if ((!found)) {
                    for (extension_names) |ext_name| {
                        if (std.mem.eql(u8, (if (@typeInfo(@TypeOf(decl)) == .@"enum" or @typeInfo(@TypeOf(decl)) == .@"union") @tagName(decl) else decl.name), ext_name)) {
                            const extension = @field(config_x, (if (@typeInfo(@TypeOf(decl)) == .@"enum" or @typeInfo(@TypeOf(decl)) == .@"union") @tagName(decl) else decl.name));
                            if (extension.hasField(field_name)) {
                                result[cp_cast_int(usize, i)] = extension.field(field_name);
                                found = true;
                                break;
                            }
                        }
                    }
                }
            }
            if ((!found)) {
                result[cp_cast_int(usize, i)] = default.field(field_name);
            }
        }
        return result;
}
